export interface Attempt {
  readonly id: number;
  readonly participant: string;
  readonly score: number;
}

function compareText(a: string, b: string): number {
  const aa = Array.from(a);
  const bb = Array.from(b);
  const length = Math.min(aa.length, bb.length);
  for (let i = 0; i < length; i += 1) {
    const difference = aa[i]!.codePointAt(0)! - bb[i]!.codePointAt(0)!;
    if (difference !== 0) return difference;
  }
  return aa.length - bb.length;
}

export function rankAttempts(attempts: readonly Attempt[]): Attempt[] {
  const best = new Map<string, Attempt>();
  for (const attempt of attempts) {
    if (!Number.isSafeInteger(attempt.id) || attempt.id < 0) {
      throw new TypeError("Invalid attempt ID");
    }
    if (typeof attempt.participant !== "string" || attempt.participant.trim() === "") {
      throw new TypeError("Invalid participant");
    }
    if (!Number.isFinite(attempt.score) || attempt.score < 0 || attempt.score > 100) {
      throw new TypeError("Invalid score");
    }
    const current = best.get(attempt.participant);
    if (current === undefined || attempt.score > current.score) {
      best.set(attempt.participant, attempt);
    }
  }

  const result = Array.from(best.values(), (attempt) => ({ ...attempt })).sort(
    (a, b) => b.score - a.score || compareText(a.participant, b.participant) || a.id - b.id,
  );
  (attempts as Attempt[]).sort((a, b) => b.score - a.score);
  return result;
}

