import { rankAttempts, Attempt } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function throwsTypeError(fn: () => void, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

const empty: readonly Attempt[] = [];
const emptyResult = rankAttempts(empty);
deepEqual(emptyResult, [], 'empty input returns empty output');
assert(emptyResult !== empty, 'empty output is a new array');

const attempts: readonly Attempt[] = Object.freeze([
  Object.freeze({ id: 8, participant: 'bob', score: 80 }),
  Object.freeze({ id: 2, participant: 'alice', score: 90 }),
  Object.freeze({ id: 5, participant: 'bob', score: 95 }),
  Object.freeze({ id: 1, participant: 'bob', score: 95 }),
  Object.freeze({ id: 7, participant: 'é', score: 70 }),
  Object.freeze({ id: 6, participant: 'a', score: 70 }),
  Object.freeze({ id: 4, participant: '😀', score: 70 })
]);
const before = JSON.stringify(attempts);
const ranked = rankAttempts(attempts);
deepEqual(ranked, [
  { id: 5, participant: 'bob', score: 95 },
  { id: 2, participant: 'alice', score: 90 },
  { id: 6, participant: 'a', score: 70 },
  { id: 7, participant: 'é', score: 70 },
  { id: 4, participant: '😀', score: 70 }
], 'deduplicates, retains earliest ties, and sorts by code points');
deepEqual(JSON.stringify(attempts), before, 'does not mutate or reorder input');
assert(ranked[0] !== attempts[2], 'returns fresh attempt records');

const boundaries = rankAttempts([
  { id: 0, participant: 'zero', score: 0 },
  { id: Number.MAX_SAFE_INTEGER, participant: 'hundred', score: 100 }
]);
deepEqual(boundaries, [
  { id: Number.MAX_SAFE_INTEGER, participant: 'hundred', score: 100 },
  { id: 0, participant: 'zero', score: 0 }
], 'accepts inclusive boundaries');

const invalid: Attempt[][] = [
  [{ id: -1, participant: 'x', score: 1 }],
  [{ id: 1.5, participant: 'x', score: 1 }],
  [{ id: Number.MAX_SAFE_INTEGER + 1, participant: 'x', score: 1 }],
  [{ id: 1, participant: '', score: 1 }],
  [{ id: 1, participant: '   ', score: 1 }],
  [{ id: 1, participant: 'x', score: -0.1 }],
  [{ id: 1, participant: 'x', score: 100.1 }],
  [{ id: 1, participant: 'x', score: Number.NaN }],
  [{ id: 1, participant: 'x', score: Number.POSITIVE_INFINITY }]
];
for (const records of invalid) {
  throwsTypeError(() => rankAttempts(records), `rejects invalid record ${JSON.stringify(records)}`);
}

throwsTypeError(() => rankAttempts([
  { id: 1, participant: 'valid', score: 50 },
  { id: -1, participant: 'invalid', score: 10 }
]), 'validates all records before returning');

